const split = (value: string): string[] => value.split("~").map(part => part.trim());
export const freshVocabularyBank: (VocabularyEntry & { source: "ai"; quality: "ai-unreviewed" })[] = Object.entries(rows).flatMap(([topic, block]) => block.trim().split("\n").map((row, index) => {
  const fields = row.split("|");
  if (fields.length !== 11 || fields.some(field => !field.trim())) throw new Error(`Incomplete fresh vocabulary ${topic}/${index + 1}`);
  const [word, meaning, definition, ipa, partOfSpeech, cefr, collocations, examples, family, commonError, synonyms] = fields as [string, string, string, string, string, Cefr, string, string, string, string, string];
  return { id: `fresh-v-${topic.toLowerCase()}-${String(index + 1).padStart(2, "0")}`, word, meaning, definition, ipa, partOfSpeech, cefr, topic, collocations: split(collocations), examples: split(examples), family: split(family), commonError, synonyms: split(synonyms), register: cefr === "C1" ? "academic" : "neutral", source: "ai", quality: "ai-unreviewed" };
}));
